        speech: 'كيف نكامل حاصل ضرب دالتين؟ هنا يأتي التكامل بالتجزئة. القانون: تكامل يو دي في يساوي يو في ناقص تكامل في دي يو. مثال: تكامل إكس في إي أس إكس. نختار يو تساوي إكس، ودي في تساوي إي أس إكس دي إكس. بالتعويض نحصل على إكس في إي أس إكس ناقص إي أس إكس زائد الثابت. الفكرة أننا نستبدل تكاملاً صعباً بتكامل أسهل.'
